content.content:
{
  "permissions": {
    "allow": [
      "Bash(git rm *)"
    ]
  },
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Skill",
        "hooks": [
          {
            "type": "command",
            "command": "jq -c '{ts: (now|todate), session: .session_id, skill: .tool_input.skill, args: .tool_input.args}' >> \"$CLAUDE_PROJECT_DIR/docs/evidence/skill-invocations.log\""
          }
        ]
      }
    ]
  }
}

